template<class T> class vector
{
public:
  typedef T* iterator;
  typedef const T* const_iterator;

  T* start;
  T* finish;
  T* end_of_storage;

  iterator begin() { return start; }
  const_iterator begin() const { return start; }
  iterator end() { return finish; }
  const_iterator end() const { return finish; }
  bool empty() const { return begin() == end(); }
  void resize(unsigned int n);
  void push_back(const T& x)
  {
    if (finish != end_of_storage)
      *finish++ = x;
    else
      insert_aux(end(), x);
  }

private:
  void insert_aux(iterator position, const T& x);
};

class beam_effect
{
public:
  virtual beam_effect* make_instance(beam *the_beam);
};

template<class T> class instance_bank
{
public:
  T* new_instance(T* ptr);
};

extern instance_bank<material> material_bank;

class beam : public entity
{
  rational_t thickness;
  rational_t max_length;
  color32 my_color;
  vector<beam_effect*> effects;
  material* my_material;
  bool additive;

public:
  void set_thickness(rational_t value);
  rational_t get_thickness() const;
  void set_max_length(rational_t value);
  rational_t get_max_length() const;
  void set_beam_color(const color32& value);
  color32 get_beam_color() const;
  void copy_instance_data(const beam& b);
};

void beam::copy_instance_data( const beam& b )
{
  entity::copy_instance_data( b );

  additive = b.additive;
  set_thickness( b.get_thickness() );
  set_max_length( b.get_max_length() );
  set_beam_color( b.get_beam_color() );
  if ( b.my_material != 0 )
    my_material = material_bank.new_instance( b.my_material );

  effects.resize(0);
  if ( !b.effects.empty() )
  {
    vector<beam_effect*>::const_iterator i = b.effects.begin();
    for ( ; i!=b.effects.end(); ++i )
    {
      if ( (*i) )
        effects.push_back((*i)->make_instance(this));
    }
  }
}
